solution.content:
export function mergeConfig(base, override) {
  const out = { ...base }
  for (const k of Object.keys(override)) {
    if (override[k] && typeof override[k] === 'object' && !Array.isArray(override[k]) && base[k] && typeof base[k] === 'object') out[k] = mergeConfig(base[k], override[k])
    else out[k] = override[k]
  }
  return out
}

