export function parseQuery(q) {
  return Object.fromEntries(new URLSearchParams(q))
}

solution.content:
// parseQuery(q): repeated keys collect into an array; a key seen once stays a scalar string. Values are URI-decoded. Empty input gives {}.
export function parseQuery(q) {
  const out = {}
  for (const [k, v] of new URLSearchParams(q)) {
    if (k in out) out[k] = Array.isArray(out[k]) ? [...out[k], v] : [out[k], v]
    else out[k] = v
  }
  return out
}

