// splitCsvLine(line): fields may be double-quoted; a quoted field can contain commas; inside quotes, "" is an escaped quote.
export function splitCsvLine(line) {
  return line.split(',')
}

solution.content:
// splitCsvLine(line): fields may be double-quoted; a quoted field can contain commas; inside quotes, "" is an escaped quote.
export function splitCsvLine(line) {
  const out = []
  let cur = '', inQ = false
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]
    if (inQ) {
      if (ch === '"' && line[i + 1] === '"') { cur += '"'; i++ }
      else if (ch === '"') inQ = false
      else cur += ch
    } else if (ch === '"') inQ = true
    else if (ch === ',') { out.push(cur); cur = '' }
    else cur += ch
  }
  out.push(cur)
  return out
}

