export function sortNames(names) {
  return [...names].sort()
}

solution.content:
// sortNames(names): alphabetical order, case-insensitive, ascending. Does not mutate the input.
export function sortNames(names) {
  return [...names].sort((a, b) => {
    const ka = a.toLowerCase(), kb = b.toLowerCase()
    return ka < kb ? -1 : ka > kb ? 1 : 0
  })
}

