// parseAmount(s): parses a plain decimal string ('10', '10.5', '10.55') to a number.
// Throws TypeError on anything else - callers rely on the throw to detect bad input.
export function parseAmount(s) {
  if (typeof s !== 'string' || !/^\d+(\.\d{1,2})?$/.test(s.trim())) throw new TypeError('invalid amount: ' + s)
  return Number(s)
}

