import { parseAmount } from './parseAmount.mjs'
// checkout(lines) -> { total, skipped }: lines that are not valid amounts are skipped and counted in `skipped`.
export function checkout(lines) {
  let total = 0, skipped = 0
  for (const line of lines) {
    try { total += parseAmount(line) } catch { skipped++ }
  }
  return { total, skipped }
}

